"use strict";(globalThis.webpackChunkgrc||=[]).push([[70586],{11143(e){e.exports=JSON.parse('[{"citeKey":"yildirim2026gdsight","slug":"yildirim-2026-gdsight-4e6a","title":"GDSight: Per-Operation Cross-Layer Attribution for GPUDirect Storage","authors":["I. Yildirim","X.-H. Sun","A. Kougkas"],"venue":"11th International Parallel Data Systems Workshop (PDSW 2026), held in conjunction with SC26","type":"Workshop","entryType":"inproceedings","date":"November, 2026","year":2026,"era":"iit","month":11,"abstract":"GPUDirect Storage (GDS) copies NVMe data into GPU memory, bypassing the CPU data path and the identity linking an operation to the device work it causes. To our knowledge, no external GDS tool attributes a device command to its causing application operation: cuFile stops at the call, counters report only aggregates, and time-based matching fails once submission is asynchronous, even at one operation in flight. We present GDSight, which attributes each NVMe command to the operation that caused it, whether it entered cuFile or fell back to POSIX. Using eBPF, it matches commands by timing and by physical address, and only address survives asynchrony. On unmodified KvikIO, NIXL and HDF5 we pin pathologies to their cause: a silent bypass cuFile\'s counters miss, 4\xd7 device amplification, and 22\xd7 tail inflation. We show that each diagnosis resolves to a measured intervention, worth up to 17\xd7 where throughput is the limit, or none.","hasAbstract":true,"lede":"We present GDSight, which attributes each NVMe command to the operation that caused it, whether it entered cuFile or fell back to POSIX.","links":{"code":"https://github.com/izzet/gdsight","artifact":"https://doi.org/10.5281/zenodo.22718932","program":"https://sc26.conference-program.com/presentation/?id=ws_pdsw125&sess=sess129"},"tags":["GPUDirect Storage","cuFile","NVMe","eBPF","Cross-Layer I/O Tracing","Per-Operation Attribution","Explainability"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"yildirim2026stageonce","slug":"yildirim-2026-stageonce-6b8e","title":"StageOnce: Speculative Cross-Job Data Staging for LLM Agent Fleets","authors":["I. Yildirim","X.-H. Sun","A. Kougkas"],"venue":"International Conference for High Performance Computing, Networking, Storage, and Analysis (SC 2026)","type":"Poster","entryType":"misc","date":"November, 2026","year":2026,"era":"iit","month":11,"abstract":"Scientific workflows increasingly run as fleets of LLM agents analysing immutable datasets. On a shared compute node, independent staging repeats source reads and creates storage contention, while each job discovers its inputs during reasoning. StageOnce coordinates these speculative path predictions through a node-local daemon, coalescing concurrent misses into one immutable copy while preserving dataset versions and private outputs. Tools read staged inputs directly from the filesystem, without per-read coordination. Recorded-session replays in genomics and astronomy on SSD and HDD backends reduce fleet makespan by 31-51% at 12 concurrent jobs against independent staging. Logical staging remains one copy across every tested fleet size. An ablation isolates speculation, which reduces makespan by 8-49% against reactive shared caching. StageOnce beats independent staging when fleet demand exceeds what reasoning windows can hide and reuse amortises coordination overhead, while smaller working sets can make direct reads or prologue bulk copies preferable.","hasAbstract":true,"lede":"StageOnce coordinates these speculative path predictions through a node-local daemon.","links":{"program":"https://sc26.conference-program.com/presentation/?id=rpost305&sess=sess313"},"tags":["LLM Agents","Data Staging","Speculative Execution","HPC I/O"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"yildirim2026toolfuse","slug":"yildirim-2026-toolfuse-4a7d","title":"ToolFuse: Provenance-Aware In-Flight Coalescing of Redundant Agent Tool Calls","authors":["I. Yildirim","X.-H. Sun","A. Kougkas"],"venue":"International Conference for High Performance Computing, Networking, Storage, and Analysis (SC 2026)","type":"Poster","entryType":"misc","date":"November, 2026","year":2026,"era":"iit","month":11,"abstract":"Scientific workflows increasingly run as fleets of LLM agents analysing immutable datasets. Independent agents can issue equivalent expensive read-only tool calls simultaneously, before a completed-result cache has anything to reuse. ToolFuse addresses this cold-wave gap by coalescing active calls at a gateway between agents and tool handlers. Its contribution is a provenance-aware execution identity that establishes equivalence from versioned dependencies and execution context, rather than arguments alone. Under contention on an exclusive HPC node, 16 equivalent requests become one execution, reducing CPU time by 11.79x and makespan by 2.36x. Peak memory growth falls from 6.44 GiB to 0.53 GiB. Trace replay shows that sharing depends on call duration and arrival timing. For cheap calls, coalescing remains inactive with negligible overhead. ToolFuse admits only calls declared read-only, idempotent, deterministic, and closed-world, and prefers false misses over unsafe sharing.","hasAbstract":true,"lede":"ToolFuse addresses this cold-wave gap by coalescing active calls at a gateway between agents and tool handlers.","links":{"program":"https://sc26.conference-program.com/presentation/?id=rpost306&sess=sess313"},"tags":["LLM Agents","Tool Calls","In-Flight Coalescing","Provenance"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"devarajan2026orion","slug":"devarajan-2026-orion-1c17","title":"Orion: Observability framework for hybrid workflow-centric I/O monitoring in HPC systems","authors":["H. Devarajan","R. A. O. Sinurat","I. Yildirim","O. Kogiou","A. Marathe","N. Dryden"],"venue":"8th Workshop on Programming and Performance Visualization Tools (ProTools 2026), held in conjunction with SC26","type":"Workshop","entryType":"inproceedings","date":"November, 2026","year":2026,"era":"iit","month":11,"hasAbstract":false,"links":{"program":"https://sc26.conference-program.com/presentation/?id=ws_prot104&sess=sess131"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"yildirim2026agentstage","slug":"yildirim-2026-agentstage-7c4a","title":"AgentStage: Exploiting LLM Thinking for Data Staging in Scientific Agents","authors":["I. Yildirim","X.-H. Sun","A. Kougkas"],"venue":"22nd IEEE International Conference on eScience (eScience 2026)","type":"Conference","entryType":"inproceedings","date":"September, 2026","year":2026,"era":"iit","month":9,"abstract":"LLM agents on scientific data tasks spend most of their session wall time inside tool calls reading data from storage. Yet before each tool call, the agent reasons in a thinking phase, during which the storage layer sits idle and the next tool\'s files begin to surface in the reasoning. Exploiting this is hard: the agent rarely names complete paths, so those files must be inferred and then staged before the tool fires. We present AgentStage, which reads the streaming reasoning and the agent\'s filesystem probes to identify those files, then stages them into fast local storage with in-flight decompression so the tool\'s reads land hot. We evaluate AgentStage on three curated I/O-bearing scientific tasks and one data-intensive task from each of three community benchmarks (MLE-bench, KramaBench, DSBench), across four reasoning models (three closed-weight, one open-weight). Under a paired trajectory-replay protocol that fixes each agent\'s tool sequence and varies only cold versus staged execution, AgentStage delivers an average 1.74\xd7 end-to-end speedup on the curated tasks, up to 2.34\xd7 per run. On the three community benchmarks, AgentStage delivers up to 1.36\xd7 speedup. The results show that thinking-phase staging helps when I/O share is high and prefetch completes within the thinking window, while compute-bound or many-file workloads see smaller gains. We show both conditions can be estimated before any staging run, so AgentStage\'s benefit is predictable in advance. AgentStage adds negligible LLM-side overhead and needs no per-model or per-task tuning.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2026/yildirim-2026-agentstage-7c4a.pdf"},"tags":["LLM Agents","LLM Thinking","Scientific Tasks","Data Staging","Prefetch","HPC I/O","Tiered Storage"],"_projectIds":["iowarp"],"_funding":[{"agency":"NSF","award":"OAC-2411318","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"NSF","award":"OAC-2320345","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"yildirim2026ioefficient","slug":"yildirim-2026-correct-is-not-io-efficient-9d2f","title":"Correct Is Not I/O Efficient: Characterizing I/O Behavior of LLM Agents on Scientific Data","authors":["I. Yildirim","J. Ye","J. Cernuda","X.-H. Sun","A. Kougkas"],"venue":"13th Greater Chicago Area Systems Research Workshop (GCASR 2026)","type":"Poster","entryType":"misc","date":"May, 2026","year":2026,"era":"iit","month":5,"abstract":"LLM coding agents are increasingly used to generate scientific workflows, but evaluations stop at output correctness. For data-intensive science, this is incomplete: two workflows can produce the same valid result while placing different pressure on storage systems. We study I/O behavior in correctness-passing LLM-generated scientific workflows. Contributions: a benchmark of scientific data tasks paired with expert implementations and a containerized execution harness; POSIX-level tracing of agent-emitted code via DFTracer LD_PRELOAD inside isolated subprocesses; and per-step decomposition of I/O into the final solution path versus exploration overhead (failed attempts, inspection, verification, retries). We evaluate correctness-passing agent-generated workflows across several models and scientific tasks, then compare them with expert implementations. The results show that valid agent-generated scientific code can issue far more POSIX operations and read substantially more data than expert baselines, and that exploration overhead varies by model. The takeaway is that correctness alone is not a sufficient proxy for I/O efficiency, and storage behavior should be measured directly before deploying agent-generated workflows on shared HPC or cloud storage.","hasAbstract":true,"lede":"LLM coding agents are increasingly used to generate scientific workflows, but evaluations stop at output correctness.","links":{"poster":"https://grc.iit.edu/papers/2026/yildirim-2026-correct-is-not-io-efficient-9d2f-poster.pdf","bibtex":"https://grc.iit.edu/papers/2026/yildirim-2026-correct-is-not-io-efficient-9d2f-bibtex.bib","citation":"https://grc.iit.edu/papers/2026/yildirim-2026-correct-is-not-io-efficient-9d2f-citation.txt"},"tags":["HPC","I/O Analysis","LLM Agents","Scientific Workflows","Storage Performance"],"_projectIds":["iowarp"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"lumsden2025optimizing","slug":"lumsden-2025-optimizing-rex5","title":"Optimizing I/O for an Exascale Implicit Kinetic Plasma Simulation using the Rabbit Storage System","authors":["I. Lumsden","H. Devarajan","I. Yildirim","S. Markidis","A. Hu","I. Peng","L. Pennati","D. Yokelson","S. Brink","O. Pearce","T. Scogland","B. R. de Supinski","G. L. Delzanno","A. Kougkas","X.-H. Sun","M. Taufer"],"venue":"REX-IO 2025 in conjunction with IEEE Cluster 2025 in Edinburgh, Scotland","type":"Workshop","entryType":"inproceedings","date":"September, 2025","year":2025,"era":"iit","month":9,"doi":"10.1109/CLUSTERWorkshops65972.2025.11164212","hasAbstract":false,"pages":"1\u20136","links":{"pdf":"https://grc.iit.edu/papers/2025/lumsden-2025-optimizing-rex5.pdf"},"tags":["HPC","Rabbit Nodes","I/O Accelerators","I/O Optimization","iPIC3D","IOR"],"_projectIds":[],"_funding":[{"agency":"LLNL","award":"DE-AC52-07NA27344","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yildirim2025wisio","slug":"yildirim-2025-wisio-45f7","title":"WisIO: Automated I/O Bottleneck Detection with Multi-Perspective Views for HPC Workflows","authors":["I. Yildirim","H. Devarajan","A. Kougkas","X.-H. Sun","K. Mohror"],"venue":"The 39th ACM International Conference on Supercomputing (ICS 2025)","type":"Conference","entryType":"inproceedings","date":"June, 2025","year":2025,"era":"iit","month":6,"doi":"10.1145/3721145.3725742","abstract":"Modern HPC workloads involve large data transfers that can become bottlenecks. Existing analysis tools identify bottle- necks from per-file performance data but have limitations in parallelizability and rigid heuristic-based rules, necessitating an automated, efficient, and multi-perspective solution. We designed an automated tool, WisIO, that enables parallel and distributed analysis of multi-terabyte-scale workflow performance data. WisIO examines performance data from multiple perspectives, uses metric-driven bottleneck classifi- cation, and allows extensible mapping of bottlenecks to root causes. Experimental results demonstrate that WisIO\'s multi- perspective views substantially improve bottleneck coverage, showing an average increase of up to 805\xd7 when compared to analyzing performance data from a single perspective. In our performance evaluation, WisIO\'s metric-driven classification processed 340K bottlenecks per second, while its reasoning engine handled around 35K bottlenecks per sec- ond. In an analysis of five real-world HPC workloads, WisIO demonstrated up to 11\xd7 faster analysis time and identified up to 144x more bottlenecks compared to existing solutions.","hasAbstract":true,"lede":"Modern HPC workloads involve large data transfers that can become bottlenecks.","links":{"pdf":"https://grc.iit.edu/papers/2025/yildirim-2025-wisio-45f7.pdf"},"tags":["HPC","Workflows","I/O Analysis","I/O Bottleneck Detection","WisIO","LABIOS"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"NSF","award":"OAC-2411318","agencyKnown":true},{"agency":"LLNL","award":"DE-AC52-07NA27344","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2024dftracer","slug":"devarajan-2024-dftracer-8fcb","title":"DFTracer: An Analysis-Friendly Data Flow Tracer for AI-Driven Workflows","authors":["H. Devarajan","L. Pottier","K. Velusamy","H. Zheng","I. Yildirim","O. Kogiou","W. Yu","A. Kougkas","X.-H. Sun","J.-S. Yeom","K. Mohror"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'24)","type":"Conference","entryType":"inproceedings","date":"November, 2024","year":2024,"era":"iit","month":11,"doi":"10.1109/sc41406.2024.00023","abstract":"Modern HPC workflows involve intricate coupling of simulation, data analytics, and artificial intelligence (AI) applications to improve time to scientific insight. These workflows require a cohesive set of performance analysis tools to provide a comprehensive understanding of data exchange patterns in HPC systems. However, current tools are not designed to work with an AI-based I/O software stack that requires tracing at multiple levels of the application. To this end, we developed a data flow tracer called DFTracer to capture data-centric events from workflows and the I/O stack to build a detailed understanding of the data exchange within AI-driven workflows. DFTracer has the following three novel features, including a unified interface to capture trace data from different layers in the software stack, a trace format that is analysis-friendly and optimized to support efficiently loading multi-million events in a few seconds, and the capability to tag events with workflow-specific context to perform domain-centric data flow analysis for workflows. Additionally, we demonstrate that DFTracer has a 1.44x smaller runtime overhead and 1.3-7.1x smaller trace size than state-of-the-art tracing tools such as Score-P, Recorder, and Darshan. Moreover, with AI-driven workflows, Score-P, Recorder, and Darshan cannot find I/O accesses from dynamically spawned processes, and their load performance of 100M events is three orders of magnitude slower than DFTracer. In conclusion, we demonstrate that DFTracer can capture multi-level performance data, including contextual event tagging with a low overhead of 1-5% from AI-driven workflows such as MuMMI and Microsoft\'s Megatron Deepspeed running on large-scale HPC systems. Index Terms-deep learning, workflows, I/O, tracer, multi- level, application apis, system calls, transparent, interception.","hasAbstract":true,"lede":"Modern HPC workflows involve intricate coupling of simulation, data analytics, and artificial intelligence (AI) applications to improve time to scientific insight.","links":{"pdf":"https://grc.iit.edu/papers/2024/devarajan-2024-dftracer-8fcb.pdf"},"tags":["Deep Learning","Workflows","I/O Tracing"],"_projectIds":["wisio"],"_funding":[{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true},{"agency":"LLNL","award":"DE-AC52-07NA27344","agencyKnown":true},{"agency":"NIH","award":"75N91019D00024","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yildirim2023exploringimpacts","slug":"yildirim-2023-exploring-impacts-090b","title":"Exploring the Impacts of Multiple I/O Metrics in Identifying I/O Bottlenecks","authors":["I. Yildirim","H. Devarajan","A. Kougkas","X.-H. Sun","K. Mohror"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'23), November 12-17, 2023","type":"Technical Report","entryType":"misc","date":"November, 2023","year":2023,"era":"iit","month":11,"hasAbstract":false,"links":{"poster":"https://grc.iit.edu/papers/2023/yildirim-2023-exploring-impacts-090b-poster.pdf"},"tags":["I/O Analysis","I/O Metrics","I/O Bottleneck Detection","WisIO"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yildirim2023iomax","slug":"yildirim-2023-iomax-3919","title":"IOMax: Maximizing Out-of-Core I/O Analysis Performance on HPC Systems","authors":["I. Yildirim","H. Devarajan","A. Kougkas","X.-H. Sun","K. Mohror"],"venue":"The International Parallel Data Systems Workshop (PDSW\'23)","type":"Workshop","entryType":"inproceedings","date":"November, 2023","year":2023,"era":"iit","month":11,"doi":"10.1145/3624062.3624191","abstract":"I/O analysis is an essential task for improving the performance of scientific applications on high-performance computing (HPC) systems. However, current analysis tools, which often use data drilling techniques (iterative exploration for deeper insights), treat every query independently and do not optimize column data for data-slicing (extracting specific data subsets), resulting in subpar querying performance. In this paper, we designed IOMax, a tool for efficient data drilling analysis on large-scale I/O traces. IOMax utilizes a novel query optimization technique to improve the query performance by 8.6x while reducing the memory footprint required for analysis by 11x. Additionally, it employs data transformation techniques to improve data-slicing performance by up to 11.4x. In conclusion, IOMax optimizes I/O analysis for scientific workflows on the Lassen supercomputer, resulting in up to 7x improvement.","hasAbstract":true,"lede":"We designed IOMax, a tool for efficient data drilling analysis on large-scale I/O traces.","links":{"pdf":"https://grc.iit.edu/papers/2023/yildirim-2023-iomax-3919.pdf"},"tags":["I/O Analysis","Out-of-Core Analysis","Data Drilling","WisIO"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"LLNL","award":"DE-AC52-07NA27344","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yildirim2022multifacetedapproach","slug":"yildirim-2022-multifaceted-approach-da2d","title":"A Multifaceted Approach to Automated I/O Bottleneck Detection for HPC Workloads","authors":["I. Yildirim","H. Devarajan","A. Kougkas","X.-H. Sun","K. Mohror"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'22)","type":"Poster","entryType":"misc","date":"November, 2022","year":2022,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2022/yildirim-2022-multifaceted-approach-da2d.pdf","poster":"https://grc.iit.edu/papers/2022/yildirim-2022-multifaceted-approach-da2d-poster.pdf"},"tags":["I/O Characterization","I/O Bottleneck Detection","WisIO"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yildirim2021performanceanalysis","slug":"yildirim-2021-performance-analysis-f217","title":"Performance Analysis of Containerized OrangeFS in HPC Environment","authors":["I. Yildirim","M. Tang","A. Kougkas","X.-H. Sun"],"venue":"The 2021 International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'21), November 14\u201319, 2021","type":"Poster","entryType":"misc","date":"November, 2021","year":2021,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2021/yildirim-2021-performance-analysis-f217.pdf","poster":"https://grc.iit.edu/papers/2021/yildirim-2021-performance-analysis-f217-poster.pdf"},"tags":["HPC","Singularity","Containers","Benchmarking"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"}]')}}]);